 public static class ProactiveConversationUiTests
 {
  static int checks;static void Check(bool value,string message){if(!value)throw new Exception(message);checks++;Console.WriteLine("PASS "+message);}
  [STAThread] public static int Main()
  {
   var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext());string root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"proactive-reply-ui-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);PetWindow pet=null;
   try{
    var settings=new PetSettings{GreetingEnabled=true,AiGreetingEnabled=false,AutoUpdate=false,FollowCursor=false,Wander=false,SaveChatHistory=false,OnboardingState="completed",AgentEnabled=true,ReadReplies=false,Text=new ConnectionSettings{BaseUrl="http://127.0.0.1:1/v1",Model="fixture"}};foreach(var key in settings.Hotkeys.Keys.ToArray())settings.Hotkeys[key]="";
    var vision=new TextProviderSettings{Id="fallback",Name="fallback",Connection=new ConnectionSettings{BaseUrl="http://127.0.0.1:2/v1",Model="vision"},Models=new List<string>{"vision"}};vision.ModelCapabilities["vision"]=new ModelCapabilitySetting{Images=CapabilitySupport.Supported};vision.Normalize();settings.Text.ImageSupport=CapabilitySupport.Unsupported;settings.TextProviders.Add(vision);settings.ImageDescriptionModel=new ModelReference{ProviderId="fallback",ModelId="vision"};
    pet=new PetWindow(null,settings,new SettingsStore(Path.Combine(root,"settings.json")),null);pet.Show();Pump();pet.PlayAction("idle",0);
    typeof(PetWindow).GetMethod("ShowGreeting",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(pet,null);Pump();
    var id=(string)typeof(PetWindow).GetField("lastProactiveEventId",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(pet);Check(!String.IsNullOrEmpty(id),"shown ordinary greeting has a reply event");
    pet.ShowQuickChat();Pump();var old=app.Windows.OfType<QuickChatWindow>().Single(w=>w.IsVisible);var oldInput=Find<MarkdownEditor>(old,"QuickMessageInput");oldInput.Text="existing draft";
    var oldComposer=(ConversationComposer)typeof(QuickChatWindow).GetField("composer",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(old);oldComposer.AddAttachments(new[]{ChatAttachment.FromText("old.txt","old attachment")});
    var oldSession=(ConversationSession)typeof(QuickChatWindow).GetField("session",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(old);var pendingApi=new PendingApi();typeof(ConversationSession).GetField("api",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(oldSession,pendingApi);var pending=oldSession.SendTextAsync("existing task",pet.ConversationSettings(oldSession),pet.Skin.Name);PumpUntil(()=>pendingApi.Calls==1);
    pet.OpenProactiveReply(id);Pump();var windows=app.Windows.OfType<QuickChatWindow>().Where(w=>w.IsVisible).ToArray();Check(windows.Length==2 && oldInput.Text=="existing draft" && oldComposer.SnapshotPendingAttachments().Count==1 && !pending.IsCompleted,"old quick draft, attachment and running task remain available");
    var reply=windows.Single(w=>!ReferenceEquals(w,old));var replySession=(ConversationSession)typeof(QuickChatWindow).GetField("session",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(reply);Check(replySession.History.Messages.Count(m=>m.Source=="proactive")==1,"reply shows original assistant once");
    pet.OpenProactiveReply(id);Pump();Check(app.Windows.OfType<QuickChatWindow>().Count(w=>w.IsVisible)==2,"repeated click reuses reply window");Check(settings.AgentEnabled,"opening reply does not change global work mode");
    var composer=(ConversationComposer)typeof(QuickChatWindow).GetField("composer",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(reply);composer.AddAttachments(new[]{ChatAttachment.FromText("reply.txt","reply attachment")});Find<Button>(reply,"ExpandChat").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();
    var full=app.Windows.OfType<ChatWindow>().Single(w=>w.IsVisible);var fullSession=(ConversationSession)typeof(ChatWindow).GetField("session",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(full);Check(ReferenceEquals(replySession,fullSession),"expanded chat keeps the same session");Check(full.SnapshotPendingAttachments(replySession).Count==1,"expansion retains reply attachment");Check(oldInput.Text=="existing draft" && settings.AgentEnabled,"expansion preserves other draft and global mode");
    full.Close();pendingApi.Answer.SetResult("done");PumpUntil(()=>pending.IsCompleted);pending.GetAwaiter().GetResult();old.Close();Pump();Check(!Directory.Exists(Path.Combine(root,"conversations",replySession.KernelSession.SessionId)),"unanswered reply leaves no conversation directory");
    settings.SaveChatHistory=true;pet.OpenProactiveReply(id);Pump();var acceptedWindow=app.Windows.OfType<QuickChatWindow>().Single(w=>w.IsVisible);var acceptedSession=(ConversationSession)typeof(QuickChatWindow).GetField("session",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(acceptedWindow);var acceptedApi=new PendingApi();typeof(ConversationSession).GetField("api",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(acceptedSession,acceptedApi);var input=Find<MarkdownEditor>(acceptedWindow,"QuickMessageInput");input.Text="real reply";var beforeSave=pet.ProjectStore.BeforeSave;pet.ProjectStore.BeforeSave=delegate{throw new IOException("fixture failure");};Find<Button>(acceptedWindow,"SendQuickMessage").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();Pump();Check(input.Text=="real reply" && acceptedApi.Calls==0 && acceptedSession.History.Messages.Count==1,"failed admission preserves draft and avoids model and history writes");
    pet.ProjectStore.BeforeSave=beforeSave;var acceptedComposer=(ConversationComposer)typeof(QuickChatWindow).GetField("composer",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(acceptedWindow);acceptedComposer.AddAttachments(new[]{ChatAttachment.CreateImage("first.png",new byte[]{137,80,78,71,13,10,26,10}),ChatAttachment.FromText("remove.txt","submitted attachment")});Find<Button>(acceptedWindow,"SendQuickMessage").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));PumpUntil(()=>acceptedApi.Calls==1);
    Find<Button>(acceptedWindow,"ExpandChat").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();var activeFull=app.Windows.OfType<ChatWindow>().Single(w=>w.IsVisible);var activeInput=Find<MarkdownEditor>(activeFull,"MessageInput");var fullComposer=(ConversationComposer)typeof(ChatWindow).GetField("composer",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(activeFull);fullComposer.AddAttachments(new[]{ChatAttachment.FromText("later.txt","later attachment")});var removedCard=All<Border>(activeFull).Single(b=>b.Name=="AttachmentCard" && (string)b.ToolTip=="remove.txt");Find<Button>(removedCard,"RemoveAttachment").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
    var caption=acceptedApi.Answer;acceptedApi.Answer=new TaskCompletionSource<string>();caption.SetResult("[\"description\"]");PumpUntil(()=>acceptedApi.Calls==2);Pump();Check(fullComposer.SnapshotPendingAttachments().Any(a=>a.Name=="later.txt") && !fullComposer.SnapshotPendingAttachments().Any(a=>a.Name=="remove.txt") && activeInput.Text=="real reply","added attachment and removal survive delayed first admission across expanded views");Check(acceptedApi.Messages.Last().Attachments!=null && acceptedApi.Messages.Last().Attachments.Any(a=>a.Name=="remove.txt") && !acceptedApi.Messages.Last().Attachments.Any(a=>a.Name=="later.txt"),"later attachment is absent from first request");Check(acceptedSession.History.Messages.Any(m=>m.Role=="user" && m.Content=="real reply"),"successful admission preserves real user turn");Check(acceptedApi.Messages.Any(m=>m.Role=="assistant" && m.Source=="proactive" && m.TurnId=="proactive-"+id),"model request contains the exact original proactive event");
    var busySkin=pet.Skin;var busyOther=pet.Catalog.Skins.First(s=>s.Id!=busySkin.Id && !s.IsPlaceholder);var denied=pet.RequestSkinAsync(busyOther,CompanionSelectionOrigin.Settings,null);PumpUntil(()=>denied.IsCompleted);
    Check(!denied.GetAwaiter().GetResult() && ReferenceEquals(pet.Skin,busySkin) && acceptedSession.IsBusy && activeInput.Text=="real reply" && fullComposer.SnapshotPendingAttachments().Any(a=>a.Name=="later.txt"),"active reply rejects companion selection without cancelling business or losing the draft and attachments");
    var definition=pet.ProjectStore.Load().UnassignedConversations.Single(c=>c.Id==acceptedSession.KernelSession.SessionId);Check(definition.Origin=="proactive" && settings.AgentEnabled,"admission stores proactive owner without switching global mode");acceptedApi.Answer.SetResult("answer");PumpUntil(()=>!acceptedSession.IsBusy);var flush=acceptedSession.FlushHistoryAsync();PumpUntil(()=>flush.IsCompleted);flush.GetAwaiter().GetResult();var saved=new HistoryStore(Path.Combine(root,"conversations",definition.Id,"history")).Load(definition.PetId);Check(saved.Any(m=>m.Source=="proactive" && m.TurnId=="proactive-"+id) && saved.Any(m=>m.Role=="user" && m.Content=="real reply"),"accepted reply persists original event and actual user message; saved="+saved.Count+" warning="+acceptedSession.HistoryWarning);    Pump();int beforeSwitchCalls=acceptedApi.Calls;fullComposer.ReplacePendingAttachments(fullComposer.SnapshotPendingAttachments().Where(a=>a.Name=="later.txt"));activeInput.Text="held for original companion";var originalSkin=pet.Skin;settings.PersonaOverrides[originalSkin.Id]="OWNER={pet_name}";settings.SystemPrompt="OWNER={pet_name}";var other=pet.Catalog.Skins.First(s=>s.Id!=originalSkin.Id && !s.IsPlaceholder);Check(FeedbackRemaining(pet)>0 && !acceptedSession.IsBusy && !acceptedSession.NeedsExecutionReconciliation,"completed reply feedback is still playing with no active session business before companion selection");Check(PrivateFlag(pet,"HolidayBusinessBusy") && !PrivateFlag(pet,"CompanionBusinessBusy") && !PrivateFlag(pet,"OfficialSafe"),"completed feedback still defers automatic publication while allowing explicit companion selection");Check(pet.SelectSkin(other),"switching companions with retained reply succeeds; "+SwitchState(pet));Pump();Check(!pet.ProactiveSessionOwnerCurrent(acceptedSession),"retained session is marked as belonging to original companion");var retainedQueue=(ConversationQueue)typeof(ChatWindow).GetField("queue",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(activeFull);bool queueBlocked=false;try{retainedQueue.Enqueue("must not send");}catch(InvalidOperationException){queueBlocked=true;}Check(queueBlocked && retainedQueue.Items.Count==0,"owner gate also blocks direct queue admission");Find<Button>(activeFull,"SendMessage").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();Check(acceptedApi.Calls==beforeSwitchCalls && activeInput.Text=="held for original companion","other companion cannot send retained reply or discard draft: calls="+acceptedApi.Calls+" before="+beforeSwitchCalls+" draft="+activeInput.Text);Check(pet.SelectSkin(originalSkin),"switching back to original companion succeeds; "+SwitchState(pet));Pump();Check(activeFull.IsVisible && activeInput.Text=="held for original companion","switching back restores the retained view and draft without relying on event lifetime");acceptedApi.Answer=new TaskCompletionSource<string>();Find<Button>(activeFull,"SendMessage").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));PumpUntil(()=>acceptedApi.Calls>beforeSwitchCalls);acceptedApi.Answer.SetResult("second answer");PumpUntil(()=>!acceptedSession.IsBusy);Check(acceptedApi.Messages.Any(m=>m.Role=="user" && m.Content=="held for original companion"),"switching back sends the retained draft in its original session");Check(acceptedApi.Messages[0].Content.Contains("OWNER="+originalSkin.Name),"queued reply uses original companion name and persona");
    activeFull.Close();Pump();
    Console.WriteLine("ProactiveConversationUiTests: "+checks+" assertions passed");return 0;
   }catch(Exception error){Console.WriteLine("FAIL "+error);return 1;}finally{if(pet!=null){pet.Close();Pump();}app.Shutdown();}
  }
  static bool PrivateFlag(PetWindow pet,string name){return (bool)typeof(PetWindow).GetProperty(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(pet,null);}
  static double FeedbackRemaining(PetWindow pet)
  {
   var clock=(System.Diagnostics.Stopwatch)typeof(PetWindow).GetField("watch",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(pet);
   return (double)typeof(PetWindow).GetField("completionUntil",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(pet)-clock.Elapsed.TotalSeconds;
  }
  static string SwitchState(PetWindow pet)
  {
   var flags=new[]{"CompanionBusinessBusy","HolidayBusinessBusy","HasQueuedMessages","HasActiveAgentJobs"}.Select(name=>name+"="+PrivateFlag(pet,name));
   var sessions=(IEnumerable<ConversationSession>)typeof(PetWindow).GetProperty("ConversationSessions",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(pet,null);
   return "notice="+pet.Notice+" dialogue="+pet.DialogueBusy+" dictation="+pet.DictationActive+" live="+pet.LiveActive+" "+String.Join(" ",flags)+" busySessions="+sessions.Count(s=>s.IsBusy)+" reconcileSessions="+sessions.Count(s=>s.NeedsExecutionReconciliation)+" completionFeedbackRemaining="+FeedbackRemaining(pet);
  }
  sealed class PendingApi:IConversationApi
  {
   public int Calls;public IList<ChatMessage> Messages;public TaskCompletionSource<string> Answer=new TaskCompletionSource<string>();
   public Task<string> ChatAsync(ConnectionSettings settings,IList<ChatMessage> messages,CancellationToken cancel){Messages=messages.Select(m=>m.Copy()).ToList();Interlocked.Increment(ref Calls);return Answer.Task;}
   public Task<string> TranscribeAsync(ConnectionSettings settings,byte[] audio,CancellationToken cancel){throw new NotSupportedException();}
   public Task<byte[]> SpeechAsync(ConnectionSettings settings,string voice,string text,CancellationToken cancel){throw new NotSupportedException();}public void Dispose(){}
  }
  static void PumpUntil(Func<bool> done){var limit=DateTime.UtcNow.AddSeconds(10);while(!done() && DateTime.UtcNow<limit)Pump();if(!done())throw new Exception("fixture timed out");}  static IEnumerable<T> All<T>(DependencyObject root)where T:DependencyObject{if(root is T)yield return (T)root;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)foreach(var child in All<T>(VisualTreeHelper.GetChild(root,i)))yield return child;}
  static T Find<T>(DependencyObject root,string name)where T:FrameworkElement{if(root is T && ((T)root).Name==name)return (T)root;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var found=Find<T>(VisualTreeHelper.GetChild(root,i),name);if(found!=null)return found;}return null;}
  static void Pump(){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(150)};timer.Tick+=delegate{timer.Stop();frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);}
 }
